include <robotics.scad>
// X4 Pro base plate. Origin: rotation axis on datum A (plate underside). Thickness undimensioned (1.6 assumed).
t = 1.6;
holes = [[-39.9,-5.4],[36.6,28.1],[39.7,-27.7]];  // official chain dims
tab_r = 4.6;     // gives left extremity -44.5 (110.6 envelope)
pod = [49.8, 0]; pod_r = 16.3;
$fn = 64;
difference() {
  linear_extrude(t) hull() {
    circle(r = 35.75);
    for (h = holes) translate(h) circle(r = tab_r);
  }
  for (h = holes) translate([h.x, h.y, -1]) cylinder(d = 3.2, h = t + 2);
  translate([pod.x, pod.y, -1]) cylinder(r = pod_r + 0.3, h = t + 2);   // motor pod passes through
}

