include <robotics.scad>
// Stationary frame above the PCB plus belt/motor pod. Origin: rotation axis on datum A.
// Conservative envelope solid: interior (belt, PCB parts) not dimensioned.
t_pcb = 1.6;
head_z = 21.3;      // head underside above A (scaled)
stat_top = 22.7;    // official: stationary section top above A
pod = [49.8, 0]; pod_r = 16.3; pod_bot = -7.9;   // scaled from drawing
$fn = 96;
difference() {
  union() {
    // frame: ring around head + belt cover to the motor
    translate([0,0,t_pcb]) linear_extrude(head_z - t_pcb) hull() {
      circle(r = 35.75);
      translate(pod) circle(r = pod_r);
    }
    // motor pod: below the PCB to the stationary top
    translate([pod.x, pod.y, pod_bot]) cylinder(r = pod_r, h = stat_top - pod_bot);
  }
  // clearance for the rotating head
  translate([0,0,head_z]) cylinder(d = 68.7 + 0.6, h = 30);
  // clearance around the PCB where the pod passes through it
  translate([0,0,-0.01]) linear_extrude(t_pcb + 0.01) difference() {
    hull() { circle(r = 36); for (h = [[-39.9,-5.4],[36.6,28.1],[39.7,-27.7]]) translate(h) circle(r = 4.6); }
    translate(pod) circle(r = pod_r + 0.3);
  }
}

include <robotics.scad>
// Rotating head. Origin: rotation axis at head underside (21.3 above datum A, scaled).
// Official: Ø68.7, top 41.4 above A -> height 20.1; window 10.5 tall centred at 31.7 above A.
d = 68.7; h = 41.4 - 21.3;
oc = 31.7 - 21.3; win = 10.5; recess = 0.8;
$fn = 128;
difference() {
  cyl(d = d, h = h, chamfer2 = 0.8, anchor = BOT);
  // window recess, front arc (lens span scaled from side view)
  translate([0,0,oc - win/2]) intersection() {
    difference() { cylinder(d = d + 1, h = win); translate([0,0,-1]) cylinder(d = d - 2*recess, h = win + 2); }
    translate([-29, -40, -1]) cube([54, 40, win + 2]);
  }
}

include <robotics.scad>
// IR window filling the head recess. Origin: rotation axis at optical-centre height.
d = 68.7; win = 10.5; recess = 0.8;
$fn = 128;
translate([0,0,-win/2]) intersection() {
  difference() { cylinder(d = d, h = win); translate([0,0,-1]) cylinder(d = d - 2*recess, h = win + 2); }
  translate([-29, -40, -1]) cube([54, 40, win + 2]);
}
